-- @MugTypography
-- @duration 6
-- @recommend text "123456"
-- @title MT Waves, Spring, and Wiggle
-- @author Mug
-- @version 1.0
-- @api_level 1
-- @covers mt.spring mt.wave mt.wave_square mt.wave_triangle mt.wave_sawtooth mt.wiggle
--[[ @description
Compare six stateless motion helpers: 1 wave, 2 square, 3 triangle,
4 sawtooth, 5 spring, and 6 wiggle.
]]

local kSpringCycleSeconds = 3.0

local kMotionFunctions = {
    -- 1: sine wave
    function(time)
        return mt.wave(time, 0.5)
    end,
    -- 2: square wave
    function(time)
        return mt.wave_square(time, 0.5)
    end,
    -- 3: triangle wave
    function(time)
        return mt.wave_triangle(time, 0.5)
    end,
    -- 4: sawtooth wave
    function(time)
        return mt.wave_sawtooth(time, 0.5)
    end,
    -- 5: damped spring
    function(time)
        local elapsed =
            mt.cycle(time, kSpringCycleSeconds) * kSpringCycleSeconds
        return mt.spring(elapsed, 3.0, 2.0)
    end,
    -- 6: noise-based wiggle
    function(time)
        return mt.wiggle(time, 1.0, 1.0, 2, 7)
    end,
}

function OnLayout(ctx)
    for index, evaluate in ipairs(kMotionFunctions) do
        if index <= ctx.char_count then
            local character = ctx.chars[index]
            character.offset_y = 0.5 + evaluate(ctx.time) * 0.12
            character.fill.use = true
            character.fill.color = mt.color.from_hsv((index - 1) / #kMotionFunctions, 0.7, 1.0)
        end
    end
end
